namespace $ {

	/**
	 * Per-call options for the codegen-driven request layer (assets/ui/gql,
	 * wrappers generated by `npm run codegen:ui` from co-located .graphql files).
	 * `revalidate: false` opts a call out of the refetch convention: a query does
	 * not subscribe to the invalidation marker, a mutation does not bump it.
	 */
	export type $trip2g_gql_opts = {
		revalidate?: boolean
	}

	/**
	 * POST an operation to a GraphQL endpoint, sync-over-fiber.
	 *
	 * CONVENTION: every mutation refetches every query on the current page.
	 * A query subscribes to the shared invalidation marker, a mutation bumps it,
	 * all $mol_mem-oized queries re-run ($mol_mem's deep compare stops re-renders
	 * for unchanged results). The marker lives in assets/ui/graphql/index.ts and
	 * is shared with the subscription runtime there.
	 */
	export function $trip2g_gql_post(path: string, query: string, variables?: object, opts?: $trip2g_gql_opts): unknown {
		const mutation = /^\s*mutation\b/.test(query)
		const revalidate = opts?.revalidate !== false

		// queries subscribe to the invalidation marker before fetching
		if (!mutation && revalidate) $trip2g_graphql_reset_marker_watch()

		const res = $mol_fetch.json(path, {
			method: 'POST',
			credentials: 'include',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({ query, variables }),
		}) as { data?: unknown; errors?: { message: string; path: string[] }[] }

		if (res.errors) throw new $trip2g_graphql_error('GraphQL Error', res.errors)

		// mutations bump the marker on success
		if (mutation && revalidate) $trip2g_graphql_reset_marker_bump()

		return res.data
	}

	/** Request seam used by generated *.graphql.ts wrappers (main endpoint). */
	export function $trip2g_gql_request(query: string, variables?: object, opts?: $trip2g_gql_opts): unknown {
		return $trip2g_gql_post('/_system/graphql', query, variables, opts)
	}

	/**
	 * Opaque fragment reference - what a parent's masked result carries at a
	 * `...Fragment_name` spread site, and what it passes to the component that
	 * owns the fragment. Only `<fragment_file>_unmask(ref)` gets the fields back.
	 *
	 * `\u0024` is just an escaped `$`: the $mol builder scans sources for
	 * $-names, and the masking keys (space + dollar + fragmentName/fragmentRefs)
	 * would read as phantom module references.
	 */
	export type $trip2g_gql_ref<Frag> = Frag extends { ' \u0024fragmentName'?: infer Name extends string }
		? { ' \u0024fragmentRefs'?: { [Key in Name]: Frag } }
		: never

}
